# 45 whiskey brands: (slug, name, url, verified fact, observation 1, observation 2, slide notes [(text, fx, fy)])
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
("johnnie-walker","Johnnie Walker","https://www.johnniewalker.com/","John Walker began selling whisky in his grocery shop in Kilmarnock, Scotland, in 1820.","The Striding Man was first drawn by the cartoonist Tom Browne in 1908 and has been walking ever since.","Thin, widely spaced small capitals keep the name quiet so the figure does the talking."),
("chivas-regal","Chivas Regal","https://www.chivas.com/","Brothers James and John Chivas built their business in Aberdeen, and Chivas Regal was launched in 1909.","The arched banner and crossed blades look like a Scottish coat of arms.","The age statement sits in the centre of the crest, so quality is part of the mark."),
("glenfiddich","Glenfiddich","https://www.glenfiddich.com/","William Grant and his children built the Glenfiddich distillery in Dufftown, and its first spirit ran on Christmas Day 1887.","A condensed serif wordmark looks classic, tall and confident.","The name means \"valley of the deer\" in Gaelic, which is why the brand also uses a stag."),
("the-macallan","The Macallan","https://www.themacallan.com/","The Macallan was founded in 1824 at Easter Elchies in Speyside, one of the first licensed distilleries in Scotland.","Red classic serif capitals with a small \"The\" above feel formal and traditional.","The restrained type suits a whisky sold as a luxury collectible."),
("the-glenlivet","The Glenlivet","https://www.theglenlivet.com/","George Smith founded The Glenlivet in 1824, the first legally licensed distillery in the Glenlivet parish.","Stacked green serif capitals echo the classic bottle label.","A small crest under the name adds a seal of tradition."),
("glenmorangie","Glenmorangie","https://www.glenmorangie.com/","Glenmorangie was founded in Tain, in the Scottish Highlands, in 1843.","Thin, spaced capitals make the long Gaelic name feel light and elegant.","The gold emblem is based on the pattern of the Cadboll Stone, an ancient Pictish carving found nearby."),
("laphroaig","Laphroaig","https://www.laphroaig.com/","The Johnston brothers founded Laphroaig on the island of Islay in 1815.","Plain serif capitals let the famously hard-to-pronounce name stand on its own.","The simple mark suits a whisky known for one bold, smoky flavour."),
("j-and-b","J&B","https://www.jbscotch.com/","Justerini & Brooks began as a wine merchant in London in 1749, and J&B Rare was launched in 1933.","Two red initials and an ampersand turn a long company name into a short, punchy mark.","The red type on the classic yellow label is one of the most recognisable on any bar shelf."),
("dewars","Dewar's","https://www.dewars.com/","John Dewar opened his wine and spirits shop in Perth, Scotland, in 1846.","A Celtic knot symbol gives the brand a simple Scottish icon.","A bold serif wordmark with the founding date keeps the heritage story clear."),
("jack-daniels","Jack Daniel's","https://www.jackdaniels.com/","Jack Daniel's is made in Lynchburg, Tennessee, where the company dates its distillery to 1866.","The black label with ornate white lettering is one of the most famous whiskey labels in the world.","\"Old No. 7\" in the centre is a mystery the brand has never fully explained, which only adds to the story."),
("jim-beam","Jim Beam","https://www.jimbeam.com/","The Beam family has made bourbon in Kentucky since the 1790s, and the Jim Beam name was adopted after Prohibition.","The slanted capitals look like a signature, linking the bourbon to the family.","A red seal below adds a stamp of approval."),
("makers-mark","Maker's Mark","https://www.makersmark.com/","Bill Samuels Sr. started Maker's Mark in Loretto, Kentucky, in the 1950s.","The small mark with S IV and a star stands for Samuels, fourth generation, and the family's Star Hill Farm.","The brand is just as famous for its red wax seal, created by Margie Samuels."),
("wild-turkey","Wild Turkey","https://wildturkeybourbon.com/","The name comes from a 1940 turkey hunting trip, when a distillery executive brought bourbon for his friends.","The detailed turkey illustration is a literal picture of the name.","Heavy, rugged capitals match the brand's strong, high-proof bourbon."),
("buffalo-trace","Buffalo Trace","https://www.buffalotracedistillery.com/","The distillery in Frankfort, Kentucky, is named after an old buffalo trail that crossed the Kentucky River there.","A buffalo silhouette sits between the two words, telling the name's story.","Tall, narrow capitals give the logo an old frontier feel."),
("woodford-reserve","Woodford Reserve","https://www.woodfordreserve.com/","Woodford Reserve was launched in 1996 at a historic distillery in Versailles, Kentucky.","Very widely spaced capitals feel calm, refined and premium.","The quiet wordmark matches a bourbon positioned as a sipping whiskey."),
("bulleit","Bulleit","https://www.bulleit.com/","Tom Bulleit launched Bulleit Bourbon in 1987, inspired by a recipe from his ancestor Augustus Bulleit.","Heavy capitals inside a box look like an old frontier stamp.","The orange colour matches the bourbon and stands out on the shelf."),
("four-roses","Four Roses","https://fourrosesbourbon.com/","Four Roses has been a trademarked bourbon brand since the 1880s.","According to legend, the name comes from a corsage of four roses worn by the founder's sweetheart.","Elegant condensed type and a thin ring feel romantic rather than rugged."),
("knob-creek","Knob Creek","https://www.knobcreek.com/","Knob Creek was introduced in 1992 and is named after the Kentucky farm where Abraham Lincoln lived as a boy.","Heavy slab letters look like an old newspaper headline.","The deep brown colour matches the label and the bourbon."),
("jameson","Jameson","https://www.jamesonwhiskey.com/","John Jameson took over the Bow Street distillery in Dublin in 1780.","Arched green capitals follow the shape of the classic label.","The red seal carries the family motto \"Sine Metu\", which means \"without fear\"."),
("bushmills","Bushmills","https://bushmills.com/","Bushmills in County Antrim traces its licence to distil back to 1608.","Bold capitals inside a curved badge look like an old shop sign.","The badge shape works as a label, a sign and a stamp."),
("tullamore-dew","Tullamore D.E.W.","https://www.tullamoredew.com/","Tullamore D.E.W. comes from the town of Tullamore, and its name uses the initials of Daniel E. Williams.","Stacked serif capitals make the long name easy to read.","The initials D.E.W. turn a manager's name into a word that sounds fresh and light."),
("redbreast","Redbreast","https://www.redbreastwhiskey.com/","Redbreast was first sold by Gilbey's in the early 1900s and is now a famous Irish single pot still whiskey.","The name comes from the robin, which the brand still uses on its labels.","The classic serif lettering feels old-fashioned and warm."),
("teeling","Teeling","https://teelingwhiskey.com/","The Teeling Whiskey Distillery opened in Dublin in 2015, the first new distillery in the city in over a century.","The phoenix between the words stands for the rebirth of Dublin whiskey.","Hand-drawn capitals give the brand a modern craft feel."),
("powers","Powers","https://www.powerswhiskey.com/","James Power founded his distillery in Dublin in 1791.","A diamond with a P sits under the name like a seal.","The founding date is part of the logo, so heritage is built in."),
("green-spot","Green Spot","https://spotwhiskey.com/","Green Spot was first sold by Mitchell & Son, a Dublin wine merchant, in the early 1900s.","The green dot is a literal picture of the name.","The name comes from the green paint marks the merchant put on its whiskey casks."),
("slane","Slane","https://slaneirishwhiskey.com/","The Conyngham family opened the Slane distillery on the grounds of Slane Castle in 2017.","The round seal with a star looks like a stamp of approval.","\"Triple casked\" in the seal tells you how the whiskey is made."),
("roe-and-co","Roe & Co","https://www.roeandcowhiskey.com/","Roe & Co was launched in 2017 and is named after George Roe, a famous Dublin distiller of the 1800s.","The round badge with circular text looks like a vintage coin.","The waves under the name hint at the River Liffey near the distillery."),
("suntory","Suntory","https://www.suntory.com/","Shinjiro Torii founded the company in 1899 and opened Japan's first malt whisky distillery at Yamazaki in 1923.","Bright blue rounded letters make the brand feel fresh, like water.","The company logo is friendly and modern rather than traditional."),
("nikka","Nikka","https://www.nikka.com/eng/","Masataka Taketsuru founded Nikka in 1934 at Yoichi, Hokkaido, after studying whisky making in Scotland.","The detailed crest looks like a European coat of arms, a nod to the founder's Scottish training.","The emblem appears on every bottle, so it works even without the name."),
("mackmyra","Mackmyra","https://www.mackmyra.com/","Mackmyra was founded in 1999 by eight friends and became Sweden's first single malt distillery.","Heavy, condensed capitals feel strong and Scandinavian.","The bold black wordmark stands out among the ornate labels of traditional whisky."),
("amrut","Amrut","https://www.amrutdistilleries.com/","Amrut Distilleries was founded in Bangalore, India, in 1948.","The crest with a crown and the founding date looks like a royal seal.","Ornate details give an Indian whisky the same heritage signals as Scotch."),
("paul-john","Paul John","https://www.pauljohnwhisky.com/","John Distilleries in Goa, India, launched the Paul John single malts in 2012.","The flowing signature script makes the brand feel personal.","The founder's name in handwriting works like a personal guarantee."),
("crown-royal","Crown Royal","https://www.crownroyal.com/","Crown Royal was created in 1939 for the royal visit of King George VI and Queen Elizabeth to Canada.","A crown above the script is a direct link to the royal story.","The flowing script and purple colour feel regal and celebratory."),
("canadian-club","Canadian Club","https://www.canadianclubwhisky.com/","Hiram Walker founded Canadian Club in Walkerville, Ontario, in 1858.","The bold script looks like old hand lettering on a label.","Black script on its own keeps the logo classic and simple."),
("starward","Starward","https://starward.com.au/","David Vitale founded Starward in Melbourne, Australia, in 2007.","Widely spaced gold capitals feel modern and premium.","The clean wordmark sets the brand apart from traditional whisky crests."),
("penderyn","Penderyn","https://www.penderyn.wales/","Penderyn released its first whisky in 2004, the first Welsh whisky in about a century.","Widely spaced serif capitals feel elegant and calm.","The small \"Distillery\" line below keeps the focus on the name."),
("westland","Westland","https://www.westlanddistillery.com/","Westland was founded in Seattle in 2010 to make American single malt whiskey.","The red diamond with a tree points to the forests of the Pacific Northwest.","Condensed blue capitals feel crisp and modern."),
("bruichladdich","Bruichladdich","https://www.bruichladdich.com/","Bruichladdich was founded on Islay in 1881 and reopened in 2001 after being closed.","The round seal with a decorative B monogram looks Victorian.","The bright aqua colour is rare in Scotch and makes the brand instantly recognisable."),
("kings-county","Kings County","https://kingscountydistillery.com/","Kings County Distillery was founded in Brooklyn in 2010 and works from the Brooklyn Navy Yard.","Widely spaced blue capitals feel clean and modern.","The name uses Brooklyn's official county name, Kings County."),
("whistlepig","WhistlePig","https://www.whistlepigwhiskey.com/","WhistlePig was founded on a farm in Shoreham, Vermont, in 2007 and is known for rye whiskey.","A pig in a suit is a playful mascot for a premium whiskey.","Old-style serif capitals balance the joke with a sense of tradition."),
("uncle-nearest","Uncle Nearest","https://unclenearest.com/","Fawn Weaver launched Uncle Nearest in 2017 to honour Nathan \"Nearest\" Green, who taught Jack Daniel to make whiskey.","Bold condensed capitals stack the name like a classic label.","The brand puts a forgotten master distiller's name front and centre."),
("high-west","High West","https://www.highwest.com/","David Perkins founded High West in Park City, Utah, in 2006.","The horseshoe and arched type look like an old saloon sign.","\"Distillery & Saloon\" in the badge tells you about the brand's western roots."),
("compass-box","Compass Box","https://www.compassboxwhisky.com/","John Glaser founded Compass Box in London in 2000 as a whisky blender.","Arched capitals bend like the edge of a compass.","\"Scotch whiskymakers\" underneath explains what the company does."),
("waterford","Waterford","https://waterfordwhisky.com/","Mark Reynier founded Waterford Distillery in Ireland, which began distilling in 2016.","Widely spaced blue capitals feel calm and scientific, like the brand's focus on barley.","The simple wordmark lets the labels carry detailed farm information."),
("cotswolds","Cotswolds","https://www.cotswoldsdistillery.com/","Daniel Szor founded Cotswolds Distillery in England in 2014.","A small emblem with the founding date sits above spaced capitals.","Thin lines and ornaments give a young distillery a traditional look."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 45
